examples.template:
let current = statuses.first { $0.id == statusID }
Button {
    isOpen = true
} label: {
    HStack(spacing: theme.spacing.space2) {
        if let current {
            Image(systemName: current.category.systemImage).foregroundStyle(theme.colors[role: current.category.role])
            Text(current.name)
        }
        Image(systemName: "chevron.down")
            .imageScale(.small)
    }
}
.buttonStyle(.monarch(.secondary, size: .md))
.onAppear { if startsPresented { isOpen = true } }
.popover(isPresented: $isOpen, arrowEdge: .top) {
    VStack(alignment: .leading, spacing: 0) {
        ForEach(Category.allCases, id: \.self) { category in
            let members = statuses.filter { $0.category == category }
            if !members.isEmpty {
                Text(category.name)
                    .monarchTextStyle(.caption)
                    .foregroundStyle(theme.colors.textMuted)
                    .padding(.horizontal, theme.spacing.space3)
                    .padding(.top, theme.spacing.space2)
                ForEach(members) { status in
                    Button {
                        statusID = status.id
                        isOpen = false
                    } label: {
                        HStack(spacing: theme.spacing.space2) {
                            Image(systemName: category.systemImage)
                                .foregroundStyle(theme.colors[role: category.role])
                                .frame(width: 20)
                            Text(status.name).monarchTextStyle(.body)
                            Spacer(minLength: theme.spacing.space4)
                            if statusID == status.id {
                                Circle().fill(theme.colors.accentSolid).frame(width: 6, height: 6)
                            }
                        }
                        .foregroundStyle(theme.colors.textDefault)
                        .padding(.horizontal, theme.spacing.space3)
                        .frame(minHeight: 44)
                        .contentShape(Rectangle())
                    }
                    .buttonStyle(.plain)
                    .accessibilityAddTraits(statusID == status.id ? .isSelected : [])
                }
            }
        }
    }
    .padding(.vertical, theme.spacing.space1)
    .frame(minWidth: 220)
    .presentationCompactAdaptation(.popover)
    .presentationBackground(theme.colors.bgSurface)
}

examples.setupTemplate:
@Environment(\.monarchTheme) private var theme
@Environment(\.monarchStartsPresented) private var startsPresented
@State private var isOpen = false
@State private var statusID = {{value}}

private enum Category: CaseIterable {
    case backlog, unstarted, started, completed, cancelled

    var name: String {
        switch self {
        case .backlog: "Backlog"
        case .unstarted: "Not started"
        case .started: "In progress"
        case .completed: "Completed"
        case .cancelled: "Cancelled"
        }
    }

    var systemImage: String {
        switch self {
        case .backlog: "circle.dashed"
        case .unstarted: "circle"
        case .started: "circle.righthalf.filled"
        case .completed: "checkmark.circle.fill"
        case .cancelled: "xmark.circle.fill"
        }
    }

    var role: MonarchColorRole {
        switch self {
        case .backlog, .cancelled: \.textSubtle
        case .unstarted: \.textMuted
        case .started: \.warningStrong
        case .completed: \.successStrong
        }
    }
}

private struct Status: Identifiable {
    let id: String
    let name: String
    let category: Category
}

private let statuses = [
    Status(id: {{statuses.0.id}}, name: {{statuses.0.name}}, category: {{statuses.0.category|case}}),
    Status(id: {{statuses.1.id}}, name: {{statuses.1.name}}, category: {{statuses.1.category|case}}),
    Status(id: {{statuses.2.id}}, name: {{statuses.2.name}}, category: {{statuses.2.category|case}}),
